/**
 * Whiteboard hand overlay — a photo-real hand that tracks the pen position.
 *
 * The whole rig is data: `handAssets.ts` (generated by scripts/build-hand-assets.mjs) holds one
 * PNG per hand/tool, and each entry publishes the *working point* — the marker nib, pencil
 * point, chalk end, centre of the eraser pad, or the fingertips of the flat palm — as `ax,ay`
 * inside the image. Drawing the image at (pen − anchor) is therefore the entire hand rig: no
 * per-asset calibration, no path math, and it stays pixel-accurate at any zoom.
 *
 * This replaces the previous ~500-line hand-authored SVG hand. Photos were generated
 * image plates: drawn vector hands look like cartoons no matter how many gradients you
 * add, which is why every mature whiteboard engine ships a photographed hand
 * (docs/WHITEBOARD_HAND.md §2).
 */
import { memo, useEffect, useState } from 'react'
import { getHandFrame, inkDotFor, plateFor, subscribeHandFrame, type HandFrame } from './hand'
import { handAsset, handDrawHeight, handDrawWidth } from './handAssets'

/**
 * Which photo to show. `style` picks the tool; the pose (pen vs flat palm) decides between
 * the pen grips and the bare palm used for the "push" effect, and an eraser always wins.
 */
export const HandOverlay = memo(function HandOverlay({ slideId }: { slideId?: string }) {
  void slideId
  // Starting from the live frame (not a blank one) matters: when several slide previews
  // mount mid-playback, the hand must not flash in the corner before the first broadcast.
  const [frame, setFrame] = useState<HandFrame>(getHandFrame)

  useEffect(() => subscribeHandFrame(setFrame), [])

  if (!frame.active || frame.opacity <= 0.01) return null

  const key = plateFor(frame)
  const asset = handAsset(key)
  const w = handDrawWidth(asset)
  const h = handDrawHeight(asset)
  // design px per natural px — the anchor (ax, ay) is stored in natural pixels
  const k = h / asset.natH
  const ax = asset.ax * k
  const ay = asset.ay * k
  const dot = inkDotFor(key)
  const flip = frame.side === 'left' ? -1 : 1
  // a pressed tool sits ~1% closer to the board: the nib stays, the hand eases in
  const press = frame.pressing ? 0.99 : 1
  // text ink sizes the rig to the type (a caption must not get a headline-sized hand)
  const fit = frame.scale ?? 1

  return (
    <div
      className="pointer-events-none absolute z-50 select-none"
      style={{
        left: frame.x,
        top: frame.y,
        opacity: frame.opacity,
        transform: `translate(${-ax}px, ${-ay}px) rotate(${frame.angle}deg) scale(${flip * press * fit}, ${press * fit})`,
        transformOrigin: `${ax}px ${ay}px`,
        willChange: 'transform, opacity',
        filter: 'drop-shadow(3px 5px 3px rgba(15,23,42,0.22))',
        transition: 'opacity 130ms linear',
      }}
      data-hand={key}
      data-hand-side={frame.side}
      data-hand-pose={frame.pose}
    >
      <img
        src={asset.src}
        width={w}
        height={h}
        alt=""
        draggable={false}
        style={{ display: 'block', width: w, height: h, pointerEvents: 'none' }}
      />
      {/*
        Two cheap cues that sell the contact, both anchored to the working point: a soft
        contact patch (the tool pressing the board) and — for tools that actually leave ink —
        a faint dot of the right colour. An eraser gets the patch but never an ink dot.
      */}
      <span
        aria-hidden
        style={{
          position: 'absolute',
          left: ax - 22,
          top: ay - 22,
          width: 44,
          height: 44,
          borderRadius: '50%',
          background: 'radial-gradient(circle, rgba(15,23,42,0.26) 0%, rgba(15,23,42,0.10) 45%, rgba(15,23,42,0) 72%)',
          opacity: frame.pressing ? 1 : 0.5,
          transition: 'opacity 90ms linear',
        }}
      />
      {dot ? (
        <span
          aria-hidden
          style={{ position: 'absolute', left: ax - 3, top: ay - 3, width: 6, height: 6, borderRadius: '50%', background: dot, opacity: frame.pressing ? 0.85 : 0.4 }}
        />
      ) : null}
    </div>
  )
})
